// BIND-7d: the C# arm of accessor-capstone, the third language beside C++ and Rust (D-BIND-11).
//
// It reads the SAME committed files the C++ gtest (test_accessor_capstone.cpp) and the Rust
// test (accessor_capstone.rs) read:
//   - schema  : integration-tests/accessor-capstone/proto/accessor_capstone.proto, generated by
//               this project's FletcherGen target with csharp,csharp_model_only,csharp_accessor
//   - fixture : integration-tests/accessor-capstone/fixtures/accessor_capstone_fixture.json
//   - oracle  : integration-tests/accessor-capstone/fixtures/accessor_capstone_expected.json
// It builds an in-memory Arrow batch from the fixture with Apache.Arrow's own arrays (not IPC,
// not the generated model, which cannot write the fixture's null elements), reads it through
// the generated CapstoneBatchAccessor, normalises every read into the oracle's shape and asserts
// observed == expected. All three arms compare with the one oracle, so the C# readout equals the
// C++ and Rust readouts transitively. No expected value is written in this file.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text.Json.Nodes;

using Apache.Arrow;
using Apache.Arrow.Types;

using Fletcher.Gen.Rba.Capstone;

using Xunit;

namespace Eiva.Fletcher.ProtocDotnet;

public sealed class CapstoneTests
{
    private static string FixturesDir() =>
        typeof(CapstoneTests).Assembly.GetCustomAttributes<AssemblyMetadataAttribute>()
            .Single(a => a.Key == "CapstoneFixturesDir").Value!;

    private static JsonObject Load(string name)
    {
        var node = JsonNode.Parse(File.ReadAllText(Path.Combine(FixturesDir(), name)))!.AsObject();
        node.Remove("_comment");
        return node;
    }

    // ---------------------------------------------------------------------------------------
    // The fixture as Arrow arrays, typed by the generated Schema, nulls where the fixture has them.
    // ---------------------------------------------------------------------------------------

    private static ArrowBuffer Validity(IEnumerable<bool> present)
    {
        var builder = new ArrowBuffer.BitmapBuilder();
        foreach (bool p in present)
        {
            builder.Append(p);
        }
        return builder.Build();
    }

    private static ArrowBuffer Offsets(IEnumerable<int> lengths)
    {
        var builder = new ArrowBuffer.Builder<int>();
        int offset = 0;
        builder.Append(offset);
        foreach (int length in lengths)
        {
            offset += length;
            builder.Append(offset);
        }
        return builder.Build();
    }

    private static Int32Array Ints(IEnumerable<JsonNode?> values)
    {
        var builder = new Int32Array.Builder();
        foreach (JsonNode? v in values)
        {
            if (v is null)
            {
                builder.AppendNull();
            }
            else
            {
                builder.Append(v.GetValue<int>());
            }
        }
        return builder.Build();
    }

    private static StringArray Strings(IEnumerable<JsonNode?> values)
    {
        var builder = new StringArray.Builder();
        foreach (JsonNode? v in values)
        {
            if (v is null)
            {
                builder.AppendNull();
            }
            else
            {
                builder.Append(v.GetValue<string>());
            }
        }
        return builder.Build();
    }

    // Child structs, a null entry a null struct (its children then hold placeholders).
    private static StructArray Children(StructType type, IReadOnlyList<JsonNode?> children)
    {
        var scores = Ints(children.Select(c => c?["score"] ?? JsonValue.Create(0)));
        var names = Strings(children.Select(c => c?["name"] ?? JsonValue.Create("")));
        int nulls = children.Count(c => c is null);
        return new StructArray(type, children.Count, new IArrowArray[] { scores, names },
            nulls == 0 ? ArrowBuffer.Empty : Validity(children.Select(c => c is not null)), nulls);
    }

    private static List<JsonNode?> Items(JsonNode? list) => list!.AsArray().ToList();

    private static RecordBatch BuildBatch(JsonObject fixture)
    {
        var rows = fixture["rows"]!.AsArray().Select(r => r!.AsObject()).ToList();
        Schema generated = CapstoneBatch.Schema;
        IArrowType TypeOf(int i) => generated.GetFieldByIndex(i).DataType;

        var id = Ints(rows.Select(r => r["id"]));
        var label = Strings(rows.Select(r => r["label"]));
        var maybeChild = Children((StructType)TypeOf(2), rows.Select(r => r["maybe_child"]).ToList());

        var samplesType = (ListType)TypeOf(3);
        var samples = new ListArray(samplesType, rows.Count, Offsets(rows.Select(r => Items(r["samples"]).Count)),
            Ints(rows.SelectMany(r => Items(r["samples"]))), ArrowBuffer.Empty, 0);

        var childrenType = (ListType)TypeOf(4);
        var children = new ListArray(childrenType, rows.Count, Offsets(rows.Select(r => Items(r["children"]).Count)),
            Children((StructType)childrenType.ValueDataType, rows.SelectMany(r => Items(r["children"])).ToList()),
            ArrowBuffer.Empty, 0);

        MapArray Map(int column, Func<MapType, List<JsonNode?>, IArrowArray> values)
        {
            var type = (MapType)TypeOf(column);
            string name = generated.GetFieldByIndex(column).Name;
            var entries = rows.SelectMany(r => Items(r[name])).Select(e => e!.AsObject()).ToList();
            var entryType = new StructType(new List<Field> { type.KeyField, type.ValueField });
            var keyValues = new StructArray(entryType, entries.Count,
                new IArrowArray[] { Strings(entries.Select(e => e["key"])), values(type, entries.Select(e => e["value"]).ToList()) },
                ArrowBuffer.Empty, 0);
            return new MapArray(type, rows.Count, Offsets(rows.Select(r => Items(r[name]).Count)), keyValues, ArrowBuffer.Empty, 0);
        }
        var scores = Map(5, (type, values) => Ints(values));
        var childByKey = Map(6, (type, values) => Children((StructType)type.ValueField.DataType, values));

        // nested_children: a list of inner lists of Child, an inner list null where the fixture's is.
        var nestedType = (ListType)TypeOf(7);
        var innerType = (ListType)nestedType.ValueDataType;
        var innerLists = rows.SelectMany(r => Items(r["nested_children"])).ToList();
        var leaves = innerLists.SelectMany(l => l is null ? Enumerable.Empty<JsonNode?>() : Items(l)).ToList();
        int nullLists = innerLists.Count(l => l is null);
        var inner = new ListArray(innerType, innerLists.Count, Offsets(innerLists.Select(l => l is null ? 0 : Items(l).Count)),
            Children((StructType)innerType.ValueDataType, leaves),
            nullLists == 0 ? ArrowBuffer.Empty : Validity(innerLists.Select(l => l is not null)), nullLists);
        var nested = new ListArray(nestedType, rows.Count, Offsets(rows.Select(r => Items(r["nested_children"]).Count)),
            inner, ArrowBuffer.Empty, 0);

        // The schema the C++ arm builds: the proto's names, its nullability, and ONLY the fixture's
        // metadata, positional per field and at schema level.
        var fieldMetadata = fixture["field_metadata"]!.AsArray();
        bool[] nullable = { false, true, true, false, false, false, false, false };
        var fields = Enumerable.Range(0, generated.FieldsList.Count).Select(i =>
        {
            var metadata = fieldMetadata[i]!.AsObject().Select(p => new KeyValuePair<string, string>(p.Key, p.Value!.GetValue<string>())).ToList();
            return new Field(generated.GetFieldByIndex(i).Name, TypeOf(i), nullable[i], metadata.Count == 0 ? null : metadata);
        });
        var schemaMetadata = fixture["schema_metadata"]!.AsObject()
            .Select(p => new KeyValuePair<string, string>(p.Key, p.Value!.GetValue<string>()));
        var schema = new Schema(fields, schemaMetadata);
        return new RecordBatch(schema,
            new IArrowArray[] { id, label, maybeChild, samples, children, scores, childByKey, nested }, rows.Count);
    }

    // ---------------------------------------------------------------------------------------
    // What the accessor reads, in the oracle's shape (its _comment states the rules).
    // ---------------------------------------------------------------------------------------

    private static JsonObject Metadata(IReadOnlyDictionary<string, string> metadata)
    {
        var o = new JsonObject();
        foreach (var (key, value) in metadata.OrderBy(p => p.Key, StringComparer.Ordinal))
        {
            o[key] = value;
        }
        return o;
    }

    private static JsonObject? Child(ChildView? child) =>
        child is ChildView c ? new JsonObject { ["score"] = c.Score, ["name"] = c.Name } : null;

    private static JsonObject Row(CapstoneBatchView v)
    {
        var samples = new JsonArray();
        for (int j = 0; j < v.Samples.Count; j++)
        {
            samples.Add(v.Samples.IsNull(j) ? null : JsonValue.Create(v.Samples[j]));
        }
        var children = new JsonArray();
        foreach (ChildView? c in v.Children)
        {
            children.Add(Child(c));
        }
        var scores = new JsonArray();
        for (int j = 0; j < v.Scores.Count; j++)
        {
            scores.Add(new JsonObject
            {
                ["key"] = v.Scores.Key(j),
                ["value"] = v.Scores.ValueIsNull(j) ? null : JsonValue.Create(v.Scores.Value(j)),
            });
        }
        var childByKey = new JsonArray();
        for (int j = 0; j < v.ChildByKey.Count; j++)
        {
            childByKey.Add(new JsonObject { ["key"] = v.ChildByKey.Key(j), ["value"] = Child(v.ChildByKey.Value(j)) });
        }
        var nested = new JsonArray();
        for (int i = 0; i < v.NestedChildren.Count; i++)
        {
            if (v.NestedChildren.IsNull(i))
            {
                nested.Add(null);
                continue;
            }
            var list = new JsonArray();
            foreach (ChildView? c in v.NestedChildren[i])
            {
                list.Add(Child(c));
            }
            nested.Add(list);
        }
        return new JsonObject
        {
            ["id"] = v.Id,
            ["label"] = v.Label,
            ["maybe_child"] = Child(v.MaybeChild),
            ["samples"] = samples,
            ["children"] = children,
            ["scores"] = scores,
            ["child_by_key"] = childByKey,
            ["nested_children"] = nested,
        };
    }

    private static JsonObject Observe(CapstoneBatchAccessor accessor)
    {
        var fieldMetadata = new JsonArray();
        for (int i = 0; i < CapstoneBatch.Schema.FieldsList.Count; i++)
        {
            fieldMetadata.Add(Metadata(accessor.FieldMetadata(i)));
        }
        var rows = new JsonArray();
        for (int r = 0; r < accessor.Length; r++)
        {
            rows.Add(Row(accessor.At(r)));
        }
        return new JsonObject
        {
            ["schema_metadata"] = Metadata(accessor.SchemaMetadata),
            ["field_metadata"] = fieldMetadata,
            ["rows"] = rows,
        };
    }

    [Fact]
    public void TheCSharpAccessorReadsTheSharedFixtureAsTheOracleSays()
    {
        JsonObject expected = Load("accessor_capstone_expected.json");
        using RecordBatch batch = BuildBatch(Load("accessor_capstone_fixture.json"));

        Assert.True(CapstoneBatchAccessor.TryMake(batch, out var accessor, out var error), error);
        JsonObject observed = Observe(accessor);

        Assert.True(JsonNode.DeepEquals(expected, observed),
            $"observed:\n{observed.ToJsonString()}\nexpected:\n{expected.ToJsonString()}");
    }

    [Fact]
    public void TheComparisonCanFail()
    {
        // The oracle comparison is not vacuous: one changed value in the readout breaks it.
        JsonObject expected = Load("accessor_capstone_expected.json");
        using RecordBatch batch = BuildBatch(Load("accessor_capstone_fixture.json"));
        Assert.True(CapstoneBatchAccessor.TryMake(batch, out var accessor, out var error), error);
        JsonObject observed = Observe(accessor);
        observed["rows"]![0]!["samples"]![1] = 8;

        Assert.False(JsonNode.DeepEquals(expected, observed));
    }
}
